      renwu = "npc",
      sentence = "Crops modified and cultivated through generations sprang up through the soil, and seasonal hunts in the mountains brought in ample meat and animal skins.",
      next = {60}
    },
    [60] = {
      beijing = 4841,
      dialog = 3,
      mask = "memory",
      music = "22_Despair",
      renwu = "npc",
      sentence = "Ore deposits buried deep under the frost also provided us with trade opportunities and sharp blades to protect ourselves.",
