    },
    [61] = {
      beijing = 4841,
      dialog = 3,
      mask = "memory",
      music = "22_Despair",
      renwu = "npc",
      sentence = "In this kingdom devoted to the Goddess of War, all its people are soldiers, but never have they attacked beyond its borders.",
