    },
    [62] = {
      beijing = 4841,
      dialog = 3,
      mask = "memory",
      music = "22_Despair",
      renwu = "npc",
      sentence = "The only pity was that the mithril and ambergold beneath the snowy mountains enticed the greedy vultures of the fertile southern lands to reach out with their despicable talons.",
