    },
    [63] = {
      beijing = 4841,
      dialog = 3,
      mask = "memory",
      music = "22_Despair",
      renwu = "npc",
      sentence = "The Emperor of the South and the Archduke of the Southeast were the first to raise the banners of war. Faced with an invading army several times the size of our own, Gavin led his troops into battle.",
