    },
    [65] = {
      beijing = 4841,
      dialog = 3,
      mask = "memory",
      music = "22_Despair",
      renwu = "npc",
      sentence = "But no one imagined that the other four nations that had long been our allies and stood alongside us against our enemies now turned their backs on us.",
      next = {66}
    },
    [66] = {
      beijing = 4841,
      dialog = 3,
      mask = "memory",
      music = "22_Despair",
      renwu = "npc",
      sentence = "With us caught between the two fronts, Divinia, the most powerful and prosperous nation of the southern lands, now aimed the might of its army in an assault on the Northlands territory.",
      next = {67}
    },
    [67] = {
      beijing = 4841,
      dialog = 3,
      mask = "memory",
      music = "22_Despair",
      renwu = "npc",
      sentence = "Every commoner and soldier in the land perished in the resistance. No one survived.",
