    },
    [68] = {
      beijing = 4841,
      dialog = 3,
      mask = "memory",
      music = "22_Despair",
      renwu = "npc",
      sentence = "Gavin and his royal cavalry finally fought their way through the enemy lines and made their way back, only to meet with the sight of a capital in flames.",
